"""Brute‑force solver for Exact Cover used in tests."""
from typing import Dict, List, Any


def solve_exact_cover(instance: Dict[str, Any]) -> bool:
    u = instance["universe_size"]
    sets: List[List[int]] = instance["sets"]
    n = len(sets)
    # Preprocess each set as bitmask
    masks = []
    for s in sets:
        mask = 0
        for e in s:
            mask |= 1 << e
        masks.append(mask)
    full = (1 << u) - 1
    # iterate over subsets of sets
    for subset in range(1 << n):
        used = 0
        ok = True
        for i in range(n):
            if (subset >> i) & 1:
                # check disjointness
                if used & masks[i]:
                    ok = False
                    break
                used |= masks[i]
        if ok and used == full:
            return True
    return False
EOF"}

